<script setup>import { onMounted, ref } from "vue"; import UserLayout from "../../layouts/UserLayout.vue"; import { notificationService } from "../../services/api"; const items = ref([]), error = ref(""); const load = async () => { try { items.value = (await notificationService.list()).data; } catch (exception) { error.value = exception.message; } }; const read = async (item) => { if (!item.est_lu) { await notificationService.read(item.id); item.est_lu = true; } }; onMounted(load);</script><template><UserLayout><section class="mx-auto max-w-4xl px-5 py-12"><h1 class="text-3xl font-bold">Notifications</h1><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><div v-else-if="!items.length" class="mt-7 rounded-2xl border border-dashed p-12 text-center text-slate-500">Aucune notification.</div><div v-else class="mt-7 space-y-3"><button v-for="item in items" :key="item.id" class="w-full rounded-2xl border p-5 text-left" :class="item.est_lu ? 'border-slate-100 bg-white' : 'border-green-200 bg-green-50'" @click="read(item)"><div class="flex justify-between gap-4"><strong>{{ item.titre }}</strong><span class="text-xs text-slate-400">{{ new Date(item.date_creation).toLocaleString('fr-FR') }}</span></div><p class="mt-2 text-sm text-slate-600">{{ item.message }}</p></button></div></section></UserLayout></template>
